    @staticmethod
    def _wrappedToolbarText(value, maximumLineLength=10):
        """Wrap an action label at natural boundaries for QToolButton.

        QToolButton does not provide word wrapping for text-under-icon mode,
        so line breaks have to be placed in QAction.iconText explicitly.
        """
        normalized = " ".join(str(value).replace("\n", " ").split())
        # Underscores and hyphens are useful visual break points, but remain
        # visible so names such as AutoCS_scaffolds keep their exact spelling.
        words = normalized.replace("_", "_ ").replace("-", "- ").split()
        if len(words) < 2:
            return normalized
        lines = []
        current = ""
        for word in words:
            candidate = word if not current else current + " " + word
            if current and len(candidate) > maximumLineLength:
                lines.append(current)
                current = word
            else:
                current = candidate
        if current:
            lines.append(current)
        # Even a short multi-word label gets two balanced lines.  This keeps
        # Export PDB/CSV and similar buttons narrow and visually consistent.
        if len(lines) == 1:
            best = min(range(1, len(words)),
                       key=lambda index: max(
                           len(" ".join(words[:index])),
                           len(" ".join(words[index:]))))
            lines = [" ".join(words[:best]), " ".join(words[best:])]
        return "\n".join(lines)

    def _wrapAllToolbarActionText(self):
        """Apply consistent automatic wrapping to every toolbar action."""
        for toolbar in (self.topToolBar, self.rightToolBar,
                        self.leftToolBar):
            for action in toolbar.actions():
                if not action.isSeparator() and action.text():
                    action.setIconText(self._wrappedToolbarText(
                                                        action.text()))

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls():
            event.accept()
        else:
            event.ignore()

    def dropEvent(self, event):
        files = [u.toLocalFile() for u in event.mimeData().urls()]
        for fname in files:
            self._dropped_file = fname
            self.actionDrop.trigger()

